package com.yjiyun.chatflows.runtime.api;
import com.fasterxml.jackson.databind.ObjectMapper; import com.sun.net.httpserver.HttpExchange; import com.yjiyun.chatflows.runtime.security.ForbiddenException; import java.io.*; import java.net.URLDecoder; import java.nio.charset.StandardCharsets; import java.util.*;
final class HttpSupport { static final ObjectMapper JSON=new ObjectMapper(); static Map<String,String> query(HttpExchange x){Map<String,String> out=new HashMap<>();String q=x.getRequestURI().getRawQuery();if(q==null)return out;for(String part:q.split("&",-1)){String[] kv=part.split("=",2);out.put(dec(kv[0]),kv.length>1?dec(kv[1]):"");}return out;} static void json(HttpExchange x,int code,Object value)throws IOException{byte[] b=JSON.writeValueAsBytes(value);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(code,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}} static void error(HttpExchange x,Exception e)throws IOException{int code=e instanceof ForbiddenException?403:e instanceof SecurityException?401:e instanceof NoSuchElementException?404:e instanceof IllegalArgumentException?400:e instanceof IOException?502:500;json(x,code,Map.of("error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));} static String bearer(HttpExchange x){return x.getRequestHeaders().getFirst("Authorization");} private static String dec(String s){return URLDecoder.decode(s,StandardCharsets.UTF_8);} }
